!function(r){function i(i){for(var t,p,o=i[0],u=i[1],m=i[2],s=0,g=[];s<o.length;s++)p=o[s],Object.prototype.hasOwnProperty.call(a,p)&&a[p]&&g.push(a[p][0]),a[p]=0;for(t in u)Object.prototype.hasOwnProperty.call(u,t)&&(r[t]=u[t]);for(c&&c(i);g.length;)g.shift()();return n.push.apply(n,m||[]),e()}function e(){for(var r,i=0;i<n.length;i++){for(var e,p=n[i],o=!0,u=1;u<p.length;u++)e=p[u],0!==a[e]&&(o=!1);o&&(n.splice(i--,1),r=t(t.s=p[0]))}return r}function t(i){if(p[i])return p[i].exports;var e=p[i]={i:i,l:!1,exports:{}};return r[i].call(e.exports,e,e.exports,t),e.l=!0,e.exports}var p={},a={11:0},n=[];t.m=r,t.c=p,t.d=function(r,i,e){t.o(r,i)||Object.defineProperty(r,i,{enumerable:!0,get:e})},t.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},t.t=function(r,i){if(1&i&&(r=t(r)),8&i)return r;if(4&i&&"object"==typeof r&&r&&r.__esModule)return r;var e=Object.create(null);if(t.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:r}),2&i&&"string"!=typeof r)for(var p in r)t.d(e,p,function(i){return r[i]}.bind(null,p));return e},t.n=function(r){var i=r&&r.__esModule?function(){return r.default}:function(){return r};return t.d(i,"a",i),i},t.o=function(r,i){return Object.prototype.hasOwnProperty.call(r,i)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],u=o.push.bind(o);o.push=i,o=o.slice();for(var m=0;m<o.length;m++)i(o[m]);var c=u;n.push([84,0]),e()}({84:function(r,i,e){"use strict";e.r(i);var t=e(0);Object(t.a)("ru","army",e(85),e(1))},85:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"轻武器","link":"ru_army#ru_army_iw"}],"model":"苏军反坦克步枪","description":"<h6>综述：</h6><p>反坦克步枪是二战期间苏军步兵常用的一种轻反坦克武器，分别有PTRD-41式和PTRS-41式两种型号，这两种反坦克枪口径相同，性能相近，都是在二战初期开始装备苏军步兵部队。从1941年至1944年间，苏联这两种反坦克枪一共生产了40多万支，数量庞大。</p><p>该反坦克枪用途广泛，苏军不但用其对付德军的轻型坦克与装甲车，还会用来打击低空的德军俯冲轰炸机，甚至在城市巷战中轰击房屋工事，整个二战期间，在苏联卫国战争各个防御与进攻的战斗中，都发挥了不少作用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_iwATRifle_10.jpg","description":"<h6>PTRD-41式反坦克步枪</h6><p></p><p>基本技术数据：</p><p>枪口径：14.5毫米；</p><p>枪长度：2000毫米，枪管长：1227毫米；</p><p>空枪重：17.3公斤；</p><p>枪口初速：1012米/秒；</p><p>弹药容量：1发。</p>","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_11.jpg","description":"<h6>PTRS-41式反坦克步枪</h6><p></p><p>基本技术数据：</p><p>枪口径：14.5毫米；</p><p>枪长度：2134毫米，枪管长：1220毫米；</p><p>空枪重：20.86公斤；</p><p>枪口初速：1012米/秒；</p><p>弹药容量：5发。</p>","caption":""}],"part2title":"战场上的苏军反坦克步枪","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_iwATRifle_20.jpg","description":"（图左）1943年，手持PTRD-41式反坦克步枪的一名苏军反坦克步兵。（图中）1942年，手持PTRD-41式反坦克步枪的一名苏军反坦克营列兵。（图右）1944年，手持PTRD-41式反坦克步枪的一名苏军902步兵团列兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_21.jpg","description":"二战东线苏联战场，苏军一处PTRD-41式反坦克步枪阵地，在反坦克枪手旁边有拿着步枪掩护的苏军士兵。这种反坦克枪的枪管特别长，它的后膛为半自动设置，但该枪射击时后座力相当大，因此战斗时必须要展开两脚架稳定地架设在地面上。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_22.jpg","description":"二战期间，受阅苏军中一个PTRD-41式反坦克步枪方阵。1941年12月，苏军正式在步兵师中编入反坦克连（三个排），每排装备9支反坦克步枪。1942年3月，又在步兵团编入反坦克连，另外在团下属三个营中加设一个反坦克连（二个排），每排配备8支反坦克步枪；这样苏军一个步兵团就拥有了75支反坦克步枪，具有强大的反坦克火力。后来师级又将反坦克连扩展为反坦克营，进一步加强了反坦克能力。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_23.jpg","description":"二战东线苏联战场，苏军一处反坦克步枪班阵地，图中靠前一支是PTRD-41式反坦克步枪，靠后一支是PTRS-41式反坦克步枪；在反坦克枪阵地上，反坦克枪手都会有持步枪或冲锋枪的苏军步兵作掩护。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_24.jpg","description":"1942年6月，东线苏联战场乌克兰地区，面对德军的猛烈进攻，苏军一个反坦克步枪排仍然顽强地坚守着阵地。一名反坦克枪手正用PTRS-41式反坦克步枪瞄准德军坦克开火，指挥战斗的排长是一名高级中士。虽然苏军这种反坦克步枪只能在500米距离内击穿25毫米装甲（用钢/钨心子弹）但在苏联卫国战争初期，已能足够对付德军的轻型坦克。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_25.jpg","description":"二战东线苏联战场，正在作战中的一处苏军阵地，阵地中一个反坦克枪手用砖墙作掩护，持一支PTRD-41式反坦克步枪向德军射击，掩体内还有一名苏军为一名头部负伤的战士包扎，可见当时战斗之激烈和残酷。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_26.jpg","description":"二战东线苏联战场，苏军两支PTRD-41式反坦克步枪正组成交叉火力向德军坦克射击。在莫斯科保卫战的多个战斗中，苏军的反坦克枪在阻击德军装甲集团的进攻中发挥了不少作用，尽管此时德军的坦克装甲已经加强，反坦克枪的子弹已难以击穿其正面装甲，但对德军的半履带装甲车、轮式装甲车与军用卡车，还是威胁很大的。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_27.jpg","description":"1941年秋，东线苏联战场，苏军一个反坦克排的士兵正在迅速进入预设阵地，准备阻击德军进攻。图中一名手持PTRS-41式反坦克步枪的反坦克枪手正弯腰快步进入战壕。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_28.jpg","description":"1943年7月，东线苏联战场，苏军一个反坦克步枪班的战士正肩扛一支PTRD-41式反坦克步枪在行进，该枪全重17.3公斤，由一名士兵携带的确有些重，特别是长途行进时，通常都由两名士兵携带。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_29.jpg","description":"1942年，东线苏联战场，列宁格勒保卫战，苏军第186步兵师在卡利累亚前线进行防御作战，该师一个反坦克小组正在用PTRD-41式反坦克步枪向德军坦克射击，旁边一名士兵正为该枪装弹，因为该枪只有一发的弹容量，所以有一名助手帮助装弹会大大提高反坦克枪的射速。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_30.jpg","description":"二战东线苏联战场，苏军一个反坦克步枪小组正在用PTRD-41式反坦克步枪向一辆迫近的德军坦克瞄准开火。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_31.jpg","description":"二战东线苏联战场，苏军一个正在作战的反坦克步枪小组，使用的是PTRS-41式反坦克步枪，由于该枪有5 发的弹容量，所以作战时可以不需要助手装填子弹。在二战后期，尽管该枪已难以击穿德军中型坦克的装甲，但苏军仍通过反坦克枪对坦克的观察窗、油箱、履带和车体装甲薄弱位置进行射击，以达到击伤的战效。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_32.jpg","description":"二战东线苏联战场，苏军一个反坦克步枪小组正在用PTRS-41式反坦克步枪对空射击。打击德军低空轰炸机也是反坦克步枪的一种用法，但由于射速太低，单枪对空射击的效果很差，但若用多支反坦克枪组成对空火力网，也会对德军飞机造成一定威胁。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_33.jpg","description":"二战东线苏联战场，在一个渡口旁，苏军一个使用PTRS-41式反坦克步枪进行对空作战的防空小组。","caption":""},{"image":"imgs/ru/army/ru_army_iwATRifle_34.jpg","description":"1943年7月，东线苏联战场，隶属苏联第6军的两名手持PTRD-41式反坦克步枪的反坦克步枪手，这两位“坦克猎手”面带微笑、表情轻松，看来对战斗胜利充满信心。","caption":""}]}')}});